// Turns the portal payload (raw text and/or rate-sheet screenshots) into an
// OpenAI chat-completions request. The route catalogue from Firestore is
// injected so the model can only emit sector/airline codes that actually exist.

const payload = $('Rate Upload Webhook').first().json.body || {};
const details = $json.details || {};

const agentId = String(payload.agent_id || '').trim();
const rawText = String(payload.raw_text || '').trim();
const images = Array.isArray(payload.images) ? payload.images : [];

if (!agentId) throw new Error('Payload is missing agent_id.');
if (!rawText && images.length === 0) {
  throw new Error('Payload has neither raw_text nor images — nothing to parse.');
}

// exportFlightDetailsForN8n keys routes as "<AIRLINE>_<SECTORNOSPACE>", e.g.
// "IX_CCJJED". ingestFaresFromN8n expects sector_code space-separated
// ("CCJ JED"), so translate here and hand the model the shape it must return.
const routes = [];
for (const key of Object.keys(details)) {
  const [airline, sector] = key.split('_');
  if (!airline || !sector || sector.length < 6) continue;
  routes.push({ airline, sector_code: sector.slice(0, 3) + ' ' + sector.slice(3) });
}

if (routes.length === 0) {
  throw new Error('No flight_details mappings returned — configure routes in the Flights tab first.');
}

const sectorCodes = [...new Set(routes.map((r) => r.sector_code))].sort();
const airlineCodes = [...new Set(routes.map((r) => r.airline))].sort();

// Rate sheets write "04 MAR" with no year. Give the model today's date in IST
// so it can roll a past month/day forward instead of hardcoding a year.
const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(new Date());

const system = [
  'You extract airfare rows from travel-agent rate sheets for Zamra Travels.',
  'Input is a WhatsApp/email text dump, one or more photos or screenshots of a rate sheet, or both together.',
  'When both text and images are present, treat them as one document and merge them — do not report the same fare twice.',
  '',
  'Today is ' + today + ' (Asia/Kolkata).',
  '',
  'VALID SECTOR CODES (use these exact strings, space-separated):',
  sectorCodes.join(', '),
  '',
  'VALID AIRLINE CODES:',
  airlineCodes.join(', '),
  '',
  'RULES',
  '1. Emit one row per date+sector+airline fare. Never invent a fare that is not shown.',
  '2. sector_code and flight_code MUST come from the lists above. If a sheet names a route or airline that is not listed, skip those rows and say so in notes.',
  '   DIRECTION IS PART OF THE SECTOR. sector_code is ORIGIN then DESTINATION, in that order. Read which airport each flight departs FROM and arrives TO and never reverse them: "CCJ JED" (Calicut to Jeddah) and "JED CCJ" (Jeddah to Calicut) are different fares, and both may be in the list — pick the one that matches the sheet.',
  '   A CONNECTION IS NOT A DESTINATION. A route printed with three or more airports is one through-fare with a change of plane: "CCJ - MCT - DXB" is Calicut to Dubai via Muscat, so sector_code is "CCJ DXB". Muscat is where the passenger changes flights, not what they bought, and two flight numbers on the row ("WY 298/609") say the same thing. Only the FIRST airport (origin) and the LAST airport (final destination) may appear in sector_code — never a sector that ends at or starts from an intermediate stop, and never one through-fare split into two rows. "CCJ-DXB via MCT" means the same route.',
  '   Also set route_text to the route exactly as the sheet prints it for that fare, verbatim and in the printed order, INCLUDING any connection points (e.g. "CCJ-JED", "CCJ/JED", "CCJ - MCT - DXB", or "Calicut to Jeddah"). It is used only to check sector_code against the sheet.',
  '3. A sheet usually names the sector and airline once in a header, then lists dates and rates beneath it. Carry that header down until a new one appears.',
  '4. sp_rate is the fare printed on the sheet, as a whole number of rupees with no separators or currency symbol. It is the supplier rate; do not add commission or markup.',
  '5. date is ISO YYYY-MM-DD. Sheets usually omit the year — pick the next occurrence of that day and month on or after today, so a month already past this year rolls into next year.',
  '6. show is "no" only when the sheet marks the fare sold out, closed, on request, or otherwise unavailable. Otherwise "yes".',
  '7. Ignore headers, footers, phone numbers, greetings, terms, and baggage notes. Baggage and flight times are set from Zamra policy, not from the sheet.',
  '8. If an image is unreadable, blurry, or cropped so a rate is ambiguous, omit that row and explain in notes. A missing row is recoverable; a wrong fare is not.',
  '',
  'Put anything you skipped, any ambiguity, and any route you could not map into notes. Keep notes under 300 characters. Use an empty string when everything parsed cleanly.',
].join('\n');

const content = [];

// Images first — media before the instruction text reads more reliably.
const ALLOWED_MEDIA = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
const skipped = [];

images.forEach((img, idx) => {
  const name = img && img.name ? img.name : 'image-' + (idx + 1);
  let mediaType = String((img && img.mime_type) || '').toLowerCase().trim();
  if (mediaType === 'image/jpg') mediaType = 'image/jpeg';
  const data = img && img.data ? String(img.data) : '';

  if (!ALLOWED_MEDIA.includes(mediaType) || !data) {
    skipped.push(name);
    return;
  }

  content.push({ type: 'text', text: 'Rate sheet image: ' + name });
  content.push({
    type: 'image_url',
    // detail:high keeps the full resolution. A rate sheet is a dense grid of
    // small digits; detail:low downsamples to 512px and misreads them.
    image_url: { url: 'data:' + mediaType + ';base64,' + data, detail: 'high' },
  });
});

if (rawText) {
  content.push({ type: 'text', text: 'Pasted rate text:\n\n' + rawText });
}

if (content.length === 0) {
  throw new Error('No usable text or images after validation. Skipped: ' + skipped.join(', '));
}

content.push({
  type: 'text',
  text: 'Extract every fare row from the material above and return it in the required JSON shape.',
});

return [{
  json: {
    agent_id: agentId,
    skipped_images: skipped,
    valid_sectors: sectorCodes,
    valid_airlines: airlineCodes,
    request: {
      model: 'gpt-5-mini',
      // Raise to 'medium' if extraction quality is poor before changing model.
      reasoning_effort: 'low',
      max_completion_tokens: 16000,
      response_format: {
        type: 'json_schema',
        json_schema: {
          name: 'rate_rows',
          strict: true,
          schema: {
            type: 'object',
            properties: {
              rows: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: {
                    sector_code: { type: 'string', description: 'Space-separated ORIGIN then DESTINATION, e.g. "CCJ JED"' },
                    route_text: { type: 'string', description: 'The whole route exactly as printed on the sheet for this fare, in the printed order, including any connection points, e.g. "CCJ-JED" or "CCJ - MCT - DXB"' },
                    flight_code: { type: 'string', description: 'Airline IATA code, e.g. "IX"' },
                    date: { type: 'string', description: 'ISO date, YYYY-MM-DD' },
                    sp_rate: { type: 'integer', description: 'Supplier rate in whole rupees' },
                    show: { type: 'string', enum: ['yes', 'no'] },
                  },
                  required: ['sector_code', 'route_text', 'flight_code', 'date', 'sp_rate', 'show'],
                  additionalProperties: false,
                },
              },
              notes: { type: 'string' },
            },
            required: ['rows', 'notes'],
            additionalProperties: false,
          },
        },
      },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content },
      ],
    },
  },
}];

// Validates the model's structured output and maps it onto the firebaseData
// shape ingestFaresFromN8n expects. Anything that fails validation is dropped
// and reported rather than written — a wrong fare reaches the public site.

const meta = $('Build Vision Request').first().json;
const response = $json;

const choice = (response.choices || [])[0];
if (!choice) throw new Error('OpenAI returned no choices: ' + JSON.stringify(response).slice(0, 300));
if (choice.message && choice.message.refusal) {
  throw new Error('Model refused to process this rate sheet: ' + choice.message.refusal);
}
if (choice.finish_reason === 'length') {
  throw new Error('Response hit the token cap — the sheet is too large to parse in one pass.');
}

const text = choice.message && choice.message.content;
if (!text) throw new Error('OpenAI returned an empty message.');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (err) {
  throw new Error('Model returned unparseable JSON: ' + err.message);
}

const validSectors = new Set(meta.valid_sectors || []);
const validAirlines = new Set(meta.valid_airlines || []);
const agentId = meta.agent_id;

// Every airport the catalogue knows. A rate sheet is full of three-letter
// tokens that are not airports ("31 AUG", "WED", "KGS"); each one would
// otherwise lengthen the printed route and move its destination.
const knownCodes = new Set();
for (const sector of validSectors) {
  for (const code of String(sector).split(' ')) if (code) knownCodes.add(code);
}

/**
 * Read route_text the way the sheet printed it: a list of stops, each holding
 * the airport codes printed there ("CCJ/COK - DXB" is two origins at one stop).
 *
 * Mirrors readPrintedRoute() in web/src/js/shared/rate-route.js, which the
 * admin upload preview uses — this Code node runs in n8n's sandbox and cannot
 * import it, so the two are deliberate copies. Change one, change the other.
 * The only difference: every alternative stays a candidate here, because the
 * correction below has to land on a sector that is actually sellable.
 */
function printedRoute(routeText) {
  const raw = String(routeText || '').toUpperCase();
  const stopsIn = (text) => String(text)
    .split(/[\s\-–—>→⇒,;:|]+/)
    .map((seg) => (seg.match(/\b[A-Z]{3}\b/g) || []).filter((code) => knownCodes.has(code)))
    .filter((codes) => codes.length > 0);

  // "CCJ-DXB via MCT" states the connection after the sector, where the
  // last-stop rule would otherwise read Muscat as the destination.
  const viaAt = raw.search(/\bVIA\b/);
  let stops = stopsIn(viaAt === -1 ? raw : raw.slice(0, viaAt));
  const trailing = viaAt === -1
    ? []
    : stopsIn(raw.slice(viaAt)).reduce((all, stop) => all.concat(stop), []);

  // A slash means "either of these" only when another stop follows:
  // "CCJ/COK - DXB" is two origins, but "CCJ/JED" is the whole route.
  if (stops.length === 1 && stops[0].length > 1) stops = stops[0].map((code) => [code]);
  if (stops.length < 2) return null;

  const origins = stops[0];
  // Walk in from the end. A round trip printed "CCJ - DXB - CCJ" ends where it
  // started; the sector being sold is the outbound one.
  let destAt = -1;
  for (let i = stops.length - 1; i > 0; i--) {
    if (stops[i].some((code) => origins.indexOf(code) === -1)) { destAt = i; break; }
  }
  if (destAt === -1) return null;

  const dests = stops[destAt].filter((code) => origins.indexOf(code) === -1);
  const via = stops
    .slice(1, destAt)
    .reduce((all, stop) => all.concat(stop), [])
    .concat(trailing)
    .filter((code) => origins.indexOf(code) === -1 && dests.indexOf(code) === -1);

  return {
    origins,
    dests,
    via,
    codes: stops.reduce((all, stop) => all.concat(stop), []).concat(trailing),
  };
}

const rejected = [];
const seen = new Set();
const firebaseData = [];

for (const row of parsed.rows || []) {
  let sectorCode = String(row.sector_code || '').trim().toUpperCase();
  const flightCode = String(row.flight_code || '').trim().toUpperCase();
  const date = String(row.date || '').trim();
  const rate = Number(row.sp_rate);

  if (!validSectors.has(sectorCode)) {
    rejected.push(sectorCode + ' (unknown sector)');
    continue;
  }
  if (!validAirlines.has(flightCode)) {
    rejected.push(flightCode + ' (unknown airline)');
    continue;
  }

  const printed = printedRoute(row.route_text);
  const printedCodes = printed ? printed.codes : [];

  // Connection guard. "CCJ - MCT - DXB" is ONE Calicut->Dubai fare with a change
  // of plane in Muscat, so the sector is "CCJ DXB". A model that reads the first
  // two codes and saves "CCJ MCT" has put a Dubai price on a Muscat seat — and
  // "CCJ MCT" is usually a real sellable sector, so the validSectors check above
  // cannot catch it. Only the first and last airports may appear in sector_code;
  // anything printed between them is where the passenger changes flights.
  const [firstOrig, firstDest] = sectorCode.split(' ');
  if (printed && firstOrig && firstDest &&
      (printed.via.indexOf(firstOrig) !== -1 || printed.via.indexOf(firstDest) !== -1)) {
    const origins = printed.via.indexOf(firstOrig) !== -1 ? printed.origins : [firstOrig];
    const dests = printed.via.indexOf(firstDest) !== -1 ? printed.dests : [firstDest];
    const candidates = [];
    for (const o of origins) {
      for (const d of dests) {
        const candidate = o + ' ' + d;
        if (o !== d && validSectors.has(candidate) && candidates.indexOf(candidate) === -1) {
          candidates.push(candidate);
        }
      }
    }
    // Exactly one sellable through-sector is a correction we can trust. Zero
    // (the through route is not in the catalogue) or several (the sheet lists
    // alternative origins) is a guess, and a guessed fare is worse than none.
    if (candidates.length === 1) {
      sectorCode = candidates[0];
    } else {
      rejected.push(sectorCode + ' (connection, not a sector, on sheet "' + String(row.route_text || '').trim() + '")');
      continue;
    }
  }

  // Direction guard. The model occasionally transposes origin/destination when
  // both directions of a route are sellable, saving e.g. "JED CCJ" for a
  // Calicut->Jeddah fare. When the sheet's printed route names this sector's two
  // IATA codes in the opposite order, trust the sheet and flip sector_code — but
  // only when the corrected direction is itself a valid sector; otherwise drop
  // the row rather than save a fare pointing the wrong way.
  const [orig, dest] = sectorCode.split(' ');
  if (orig && dest) {
    const iOrig = printedCodes.indexOf(orig);
    const iDest = printedCodes.indexOf(dest);
    if (iOrig !== -1 && iDest !== -1 && iDest < iOrig) {
      const flipped = dest + ' ' + orig;
      if (validSectors.has(flipped)) {
        sectorCode = flipped;
      } else {
        rejected.push(sectorCode + ' (direction conflicts with sheet "' + String(row.route_text || '').trim() + '")');
        continue;
      }
    }
  }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(Date.parse(date + 'T00:00:00Z'))) {
    rejected.push(date + ' (bad date)');
    continue;
  }
  // Same sanity band the portal's client-side preview parser uses.
  if (!Number.isFinite(rate) || rate < 1000 || rate > 99999) {
    rejected.push(sectorCode + ' ' + date + ' (rate ' + row.sp_rate + ' out of range)');
    continue;
  }

  const key = sectorCode + '|' + flightCode + '|' + date;
  if (seen.has(key)) continue;
  seen.add(key);

  // Only what the sheet actually states. finalRate is derived server-side as
  // sp_rate + the agent's commission; baggage and flight time come from Zamra
  // policy and the flight_details mapping, never from the sheet.
  firebaseData.push({
    agent_id: agentId,
    sector_code: sectorCode,
    flight_code: flightCode,
    date,
    sp_rate: rate,
    show: row.show === 'no' ? 'no' : 'yes',
  });
}

return [{
  json: {
    firebaseData,
    parsed_count: firebaseData.length,
    rejected,
    notes: parsed.notes || '',
    skipped_images: meta.skipped_images || [],
    usage: response.usage || {},
  },
}];
